mapper.select:
SELECT count(*) FROM TBLMI_BLOCK_LST as blk LEFT JOIN TBLMI_USR as usr on blk.block_reg_usr = usr.usr_id LEFT JOIN TBLMI_COMM_CD as comm on comm.cd_id = blk.block_status and comm.grp_id = "BLOCKST" LEFT JOIN TBLMI_USR as upusr on blk.upd_id = upusr.usr_id where blk.block_status != '2'
and blk.block_type = #{block_type}
and INET_NTOA(blk.block_target) like concat('%',#{block_target},'%')
and blk.block_status = #{block_status}
and blk.block_reg_usr like concat('%',#{block_reg_usr},'%')
and usr.usr_log_id like concat('%', #{block_reg_id}, '%')
and upousr.usr_log_id like concat('%', #{block_upd_id}, '%')
and blk.block_grp_cd = #{block_grp_cd}

SELECT blk.seq as seq ,blk.block_type as block_type ,INET_NTOA(blk.block_target) as block_target ,blk.block_reg_usr as block_reg_usr ,blk.block_st_dt as block_st_dt ,blk.block_end_dt as block_end_dt ,blk.block_status as block_status ,blk.block_grp_cd as block_grp_cd ,blk.block_memo as block_memo ,blk.reg_id as reg_id ,blk.reg_dt as reg_dt ,blk.upd_id as upd_id ,blk.upd_dt as upd_dt ,comm.cd_nm as cd_nm ,usr.usr_log_id as block_reg_id ,upusr.usr_log_id as block_upd_id FROM TBLMI_BLOCK_LST as blk LEFT JOIN TBLMI_USR as usr on blk.block_reg_usr = usr.usr_id LEFT JOIN TBLMI_COMM_CD as comm on comm.cd_id = blk.block_status and comm.grp_id = "BLOCKST" LEFT JOIN TBLMI_USR as upusr on blk.upd_id = upusr.usr_id where blk.block_status != '2'
blk.block_type = #{block_type}
and INET_NTOA(blk.block_target) like concat('%',#{block_target},'%')
and blk.block_status = #{block_status}
and blk.block_reg_usr like concat('%',#{block_reg_usr},'%')
and usr.usr_log_id like concat('%', #{block_reg_id}, '%')
and upousr.usr_log_id like concat('%', #{block_upd_id}, '%')
and blk.block_grp_cd = #{block_grp_cd}
order by blk.upd_dt desc
LIMIT #{firstIndex, javaType=int}, #{recordCountPerPage, javaType=int}

mapper.update:
UPDATE TBLMI_BLOCK_LST
SET
		upd_dt = Sysdate()

			,block_type = #{block_type}


			,upd_id = #{upd_id}


			,block_status = #{block_status}


			,block_reg_usr = #{block_reg_usr}
			,reg_dt = Sysdate()


			,reg_id = #{block_reg_id}



		seq = #{seq}


		and block_target = INET_ATON(#{block_target})


		and block_grp_cd = #{block_grp_cd}

mapper.select:
SELECT count(*) FROM Tblmi_usr_hst as hst LEFT JOIN TBLMI_USR as usr on hst.usr_id = usr.usr_id
INET_NTOA(hst.usr_ip) like concat('%',#{usr_ip},'%')
and (hst.work_detail || hst.work_url) like concat('%',#{work_detail},'%')
and usr.usr_log_id = #{usr_nm}
and hst.usr_grp_cd = #{usr_grp_cd}

